/* xx_igf1_extractor.c - search raw data for IGF1.
 *
 * Scans for:
 *   DB EC at +0  ("..")
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the igf1 reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/igf1/xx_igf1.h"

static const uint8_t k_anchor0[] = { 0xDB, 0xEC };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 0U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_IGF1 };

static Abstractformat *xx_igf1_search_open(xx_io_device *window) {
    xx_igf1 *reader = xx_igf1_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_igf1_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_igf1_free((xx_igf1 *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_igf1_search_open, xx_igf1_search_close
};

static xx_format_search_state *xx_igf1_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_igf1_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_igf1_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_igf1_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_igf1_extractor = {
    xx_igf1_create_format_search,
    xx_igf1_get_current_format_info,
    xx_igf1_format_search_find_next,
    xx_igf1_free_format_search
};
